fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    debug_assert!(len > 0, "The input list must be non-empty");
    debug_assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    // Pre-allocate a new Vec with the same capacity as the original list.
    let mut new_list = Vec::with_capacity(len);

    // Push the tail portion [n..len) first...
    new_list.extend_from_slice(&list[n..]);

    // ...then push the head portion [0..n).
    new_list.extend_from_slice(&list[..n]);

    new_list
}

